-- Read-only, hash-only. Digests every existing object the seven Automations V2 files and both rollbacks reference, and
-- lists any name V2 creates that already exists. Run unchanged on production before the release and on the rehearsal
-- copy; compare with docs/plans/automations-v2/production-dependency-check-2026-11-24.json.
WITH rels(name) AS (VALUES ('private.appointment_evidence_observations'),('private.appointment_occurrences'),('private.appointment_outcome_events'),('private.automation_deferred_admissions'),('private.automation_email_senders'),('private.automation_events'),('private.automation_intake_recovery'),('private.automation_intents'),('private.automation_recipient_facts'),('private.automation_release_controls'),('private.automation_reply_watermarks'),('private.automation_runs'),('private.automation_session_revision'),('private.automation_sessions'),('private.automation_steps'),('private.dialer_disposition_receipts'),('private.policy_identities'),('public.appointments'),('public.automation_intervals'),('public.calls'),('public.campaigns'),('public.clients'),('public.company_settings'),('public.dispositions'),('public.inbound_route_attempts'),('public.lead_sources'),('public.leads'),('public.message_templates'),('public.organizations'),('public.phone_numbers'),('public.profiles'),('public.recruits'),('public.tasks'),('public.user_email_connections'),('public.wins'),('public.workflow_versions'),('public.workflows')),
fns(name) AS (VALUES ('private.affinity_phone'),('private.appointment_status_key'),('private.automation_admit_event'),('private.automation_audience_allowed'),('private.automation_block_fields'),('private.automation_builder_visible'),('private.automation_can_author'),('private.automation_capture_event'),('private.automation_channel_issue'),('private.automation_editable_graph'),('private.automation_graph_in_scope'),('private.automation_graph_issues'),('private.automation_message_status'),('private.automation_require_author'),('private.automation_session_id'),('private.automation_template_safe'),('private.automation_trigger'),('private.automation_viewer_id'),('private.automation_visible_lead'),('private.automation_workflow_access'),('private.campaign_actor'),('private.can_administer_campaign'),('private.inbounds_actor'),('private.resolve_downline_ids'),('public.automation_activity'),('public.automation_claim_work'),('public.automation_finish_node'),('public.automation_overlap'),('public.automation_process_events'),('public.automation_session_transition'),('public.automation_stop_run'),('public.can_access_voicemail'),('public.get_org_id'),('public.is_ancestor_of'),('public.publish_automation'),('public.save_automation_draft')),
created(name) AS (VALUES ('private.automation_agency_time_zone'),('private.automation_appointment_state'),('private.automation_appointment_wait'),('private.automation_awaits_restart'),('private.automation_block_available'),('private.automation_block_category'),('private.automation_callbacks_available'),('private.automation_capture_appointment_outcome'),('private.automation_capture_appointment_reopened'),('private.automation_capture_appointment_slot'),('private.automation_capture_disposition'),('private.automation_capture_issuance'),('private.automation_capture_missed_inbound'),('private.automation_capture_sale'),('private.automation_contact_owner'),('private.automation_contact_type'),('private.automation_enrolling'),('private.automation_fields_valid'),('private.automation_inbound_evidence'),('private.automation_inbound_responsible'),('private.automation_mode_unverified'),('private.automation_needs_v2'),('private.automation_observe_answered_call'),('private.automation_record_event'),('private.automation_refresh_appointment_runs'),('private.automation_restarts_for_new_time'),('private.automation_saved_message_text'),('private.automation_settle_answered_call'),('private.automation_settle_stop'),('private.automation_sms_purposes'),('private.automation_sms_resolution'),('private.automation_step_meta_valid'),('private.automation_stop_check'),('private.automation_task_receipts'),('private.automation_v2_loosened_text'),('private.automation_v2_publish_guard'),('private.automation_v2_refusal'),('private.automation_v2_rollback_guard'),('private.automation_v2_steps_needed'),('private.automation_viewing_as'),('private.automation_visible_contact'),('private.automation_waiting_out'),('private.guard_policy_issuance_append_only'),('private.guard_task_automation_provenance'),('private.policy_issuance_allowed'),('public.automation_create_task'),('public.automation_disposition_options'),('public.automation_message_timezone'),('public.automation_saved_messages'),('public.automation_sms_requirements'),('public.can_confirm_policy_issuance'),('public.claim_inbound_callback'),('public.complete_inbound_callback'),('public.confirm_policy_issuance'),('public.get_policy_issuance'),('public.inbound_callback_queue'),('public.inbound_callbacks'),('public.policy_issuance_available'),('public.policy_issuance_confirmations'),('public.release_inbound_callback')),
rel_digest AS (
  SELECT r.name, coalesce(md5(
    (SELECT concat_ws('|',c.relkind::text,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner),coalesce(c.relacl::text,'')) FROM pg_class c WHERE c.oid=to_regclass(r.name))
    ||'#'||coalesce((SELECT string_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull::text||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),'')||':'||coalesce(a.attacl::text,''),',' ORDER BY a.attname) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass(r.name) AND a.attnum>0 AND NOT a.attisdropped),'')
    ||'#'||coalesce((SELECT string_agg(k.conname||':'||pg_get_constraintdef(k.oid),',' ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=to_regclass(r.name)),'')
    ||'#'||coalesce((SELECT string_agg(ic.relname||':'||pg_get_indexdef(i.indexrelid),',' ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=to_regclass(r.name)),'')
    ||'#'||coalesce((SELECT string_agg(t.tgname||':'||t.tgenabled::text||':'||pg_get_triggerdef(t.oid),',' ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=to_regclass(r.name) AND NOT t.tgisinternal),'')
    ||'#'||coalesce((SELECT string_agg(p.polname||':'||p.polcmd::text||':'||p.polroles::regrole[]::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=to_regclass(r.name)),'')
  ),'missing') AS digest FROM rels r),
fn_digest AS (
  SELECT f.name, coalesce(md5(string_agg(p.oid::regprocedure::text||':'||md5(pg_get_functiondef(p.oid))||':'||pg_get_userbyid(p.proowner)||':'||coalesce(p.proacl::text,'')||':'||p.prosecdef::text||':'||coalesce(p.proconfig::text,''),',' ORDER BY p.oid::regprocedure::text)),'missing') AS digest
  FROM fns f LEFT JOIN pg_proc p ON p.pronamespace=split_part(f.name,'.',1)::regnamespace AND p.proname=split_part(f.name,'.',2) GROUP BY f.name)
SELECT jsonb_build_object(
  'relations',(SELECT jsonb_object_agg(name,digest) FROM rel_digest),
  'functions',(SELECT jsonb_object_agg(name,digest) FROM fn_digest),
  'created_present',(SELECT coalesce(jsonb_agg(name ORDER BY name),'[]'::jsonb) FROM created c WHERE to_regclass(c.name) IS NOT NULL
    OR EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace=split_part(c.name,'.',1)::regnamespace AND p.proname=split_part(c.name,'.',2)))) AS v2_dependencies;
